/* Deutsch Vokabular V2 service worker — generated by scripts/build-production.mjs (do not edit the
 * output). Strategy:
 *  - install: precache this release (index.html, manifest, icons, hashed /assets/*);
 *  - activate: delete the caches of older releases, take control of open pages;
 *  - navigations: NETWORK FIRST (always the newest index.html when online), cached index.html when
 *    offline — so a deployed release is picked up on the next load, never stuck on an old shell;
 *  - same-origin static files: cache first (they are content-hashed and immutable);
 *  - other origins (Firebase Auth, Firestore, Google APIs) and Firebase's /__/ paths: not touched.
 * A new release waits until the page asks it to activate («نسخهٔ تازه» notice) or all tabs close.
 */
const VERSION = '__DV2_VERSION__';
const CACHE = `dv2-${VERSION}`;
const PRECACHE = __DV2_PRECACHE__;
const NAV_TIMEOUT_MS = 6000;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('dv2-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'dv2:activate') self.skipWaiting();
});

async function navigation(request) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), NAV_TIMEOUT_MS);
  try {
    return await fetch(request, { cache: 'no-store', signal: controller.signal });
  } catch {
    const cached = await caches.match('/index.html', { cacheName: CACHE });
    return cached ?? Response.error();
  } finally {
    clearTimeout(timer);
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || url.pathname.startsWith('/__/')) return;
  if (request.mode === 'navigate') {
    event.respondWith(navigation(request));
    return;
  }
  event.respondWith(caches.match(request, { cacheName: CACHE }).then((hit) => hit ?? fetch(request)));
});
